import re
from pathlib import Path

import pytest
from packaging.version import Version

from cibuildwheel.util import resources
from cibuildwheel.util.packaging import (
    PIP_CONSTRAINT_HASHES_MIN_VERSION,
    DependencyConstraints,
    constraints_for_pip,
    parse_pip_version,
    strip_constraint_hashes,
)

HASHED_CONSTRAINTS = """\
# This file was autogenerated by uv via the following command:
#    nox -s update_constraints
build==1.6.1 \\
    --hash=sha256:51cc11666391ab6f092070437ac747002ff46f3e4113a3622177ee6b488bfc53 \\
    --hash=sha256:ecd351a4be9d35a9eaaba244a7687143c9c7d4aea6ac964e7e7ddab20cbcf4e7
    # via -r constraints.in
pip==26.2.1; implementation_name != "graalpy" \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
pip==26.1.2; implementation_name == "graalpy" \\
    --hash=sha256:cccc
    # via -r constraints.in
"""

STRIPPED_CONSTRAINTS = """\
# This file was autogenerated by uv via the following command:
#    nox -s update_constraints
build==1.6.1
    # via -r constraints.in
pip==26.2.1; implementation_name != "graalpy"
pip==26.1.2; implementation_name == "graalpy"
    # via -r constraints.in
"""


def test_defaults(tmp_path: Path) -> None:
    dependency_constraints = DependencyConstraints.pinned()

    project_root = Path(__file__).parents[1]
    resources_dir = project_root / "cibuildwheel" / "resources"

    assert dependency_constraints.base_file_path
    assert dependency_constraints.base_file_path.samefile(resources_dir / "constraints.txt")

    constraints_file = dependency_constraints.get_for_python_version(
        version="3.99", tmp_dir=tmp_path
    )
    assert constraints_file
    assert constraints_file.samefile(resources_dir / "constraints.txt")

    constraints_file = dependency_constraints.get_for_python_version(
        version="3.9", tmp_dir=tmp_path
    )
    assert constraints_file
    assert constraints_file.samefile(resources_dir / "constraints-python39.txt")

    constraints_file = dependency_constraints.get_for_python_version(
        version="3.13", tmp_dir=tmp_path
    )
    assert constraints_file
    assert constraints_file.samefile(resources_dir / "constraints-python313.txt")


def test_inline_packages(tmp_path: Path) -> None:
    dependency_constraints = DependencyConstraints(
        base_file_path=None,
        packages=["foo==1.2.3", "bar==4.5.6"],
    )

    constraint_file = dependency_constraints.get_for_python_version(version="x.x", tmp_dir=tmp_path)
    assert constraint_file
    constraints_file_contents = constraint_file.read_text()

    assert constraints_file_contents == "foo==1.2.3\nbar==4.5.6"


@pytest.mark.parametrize("config_string", ["", "latest", "packages:"])
def test_empty_constraints(config_string: str) -> None:
    dependency_constraints = DependencyConstraints.from_config_string(config_string)

    assert not dependency_constraints.packages
    assert not dependency_constraints.base_file_path
    assert dependency_constraints == DependencyConstraints.latest()


@pytest.mark.parametrize(
    "constraints_file", sorted(resources.PATH.glob("constraints*.txt")), ids=lambda p: p.name
)
def test_bundled_constraints_have_hashes(constraints_file: Path) -> None:
    text = constraints_file.read_text(encoding="utf-8")
    pins = [line for line in text.splitlines() if re.match(r"[A-Za-z0-9]", line)]

    assert pins
    for pin in pins:
        # every pin continues onto its `--hash` lines
        assert pin.endswith(" \\"), pin
    assert text.count("--hash=sha256:") >= len(pins)


def test_strip_constraint_hashes(tmp_path: Path) -> None:
    constraints = tmp_path / "constraints.txt"
    constraints.write_text(HASHED_CONSTRAINTS)

    stripped = strip_constraint_hashes(constraints, tmp_path / "stripped")

    assert stripped.read_text() == STRIPPED_CONSTRAINTS


@pytest.mark.parametrize("pip_version", ["26.0.1", "25.3", "24.0"])
def test_constraints_for_pip_strips_bundled_hashes_for_old_pip(
    tmp_path: Path, pip_version: str
) -> None:
    bundled = DependencyConstraints.pinned().get_for_python_version(
        version="3.12", tmp_dir=tmp_path
    )
    assert bundled

    result = constraints_for_pip(bundled, Version(pip_version), tmp_path)

    assert result
    assert result != bundled
    assert result.is_relative_to(tmp_path)
    text = result.read_text()
    assert "--hash" not in text
    assert "pip==" in text


@pytest.mark.parametrize("pip_version", [str(PIP_CONSTRAINT_HASHES_MIN_VERSION), "26.2.2", "27.0"])
def test_constraints_for_pip_keeps_hashes_for_new_pip(tmp_path: Path, pip_version: str) -> None:
    bundled = DependencyConstraints.pinned().get_for_python_version(
        version="3.12", tmp_dir=tmp_path
    )
    assert bundled

    assert constraints_for_pip(bundled, Version(pip_version), tmp_path) == bundled


def test_constraints_for_pip_leaves_user_files_alone(tmp_path: Path) -> None:
    user_constraints = tmp_path / "constraints.txt"
    user_constraints.write_text(HASHED_CONSTRAINTS)

    assert constraints_for_pip(user_constraints, Version("26.0.1"), tmp_path) == user_constraints
    assert constraints_for_pip(None, Version("26.0.1"), tmp_path) is None


@pytest.mark.parametrize(
    ("output", "expected"),
    [
        ("pip 26.2.2 from /venv/lib/python3.12/site-packages/pip (python 3.12)", "26.2.2"),
        ("pip 26.0.1 from C:\\venv\\Lib\\site-packages\\pip (python 3.9)\n", "26.0.1"),
        ("pip 26.3.dev0 from /src/pip (python 3.14)", "26.3.dev0"),
    ],
)
def test_parse_pip_version(output: str, expected: str) -> None:
    assert parse_pip_version(output) == Version(expected)


def test_parse_pip_version_invalid() -> None:
    with pytest.raises(ValueError, match="Unable to parse"):
        parse_pip_version("uv 0.12.10")
